G["forever/horde/50-60/04-azshara"]={faction="Horde",id="forever/horde/50-60/04-azshara",maxLevel=56,minLevel=55,next="forever/horde/50-60/05-eastern-plaguelands",steps={{goals={{map=1454,note="{npc:8659}, {object:172960}",npc=8659,npcName="Jes'rimon",quest=4300,t="turnin",title="Bone-Bladed Weapons",x=55.52,y=34.08}},title="{npc:8659}",when={{k="onquest",q={4300}}}},{goals={{area=1637,location="Orgrimmar",map=1454,npc=6929,npcName="Innkeeper Gryshka",t="sethome",x=54.1,y=68.41},{map=1454,note="{npc:15188}, {object:172957}: guárdala para {zone:1451}",npc=15188,npcName="Cenarion Emissary Blackhoof",quest=8276,t="accept",title="Taking Back Silithus",x=47.64,y=65.76},{class=true,only={classes={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}},t="train",zone=1454}},title="{area:1637}"},{goals={{map=1454,npc=7010,npcName="Zilzibin Drumlore",quest=32,t="turnin",title="Rise of the Silithid",x=56.26,y=46.68}},note="{npc:7010} trabaja en La Calle Mayor.",title="{npc:7010}",when={{k="onquest",q={32}}}},{goals={{map=1454,npc=7010,npcName="Zilzibin Drumlore",quest=4494,t="accept",title="March of the Silithid",x=56.26,y=46.68}},note="Solo si aún no has hecho {quest:4494}: {npc:7010} trabaja en La Calle Mayor. Pestlezugg la recibe en {area:976} de camino a Un'Goro en la Guía de {zone:1423}.",title="{npc:7010}",when={{k="available",minLevel=50,pre={32,7732},q=4494}}},{goals={{map=1454,t="goto",text="Maestro de vuelo de {zone:1454}",x=45.3,y=63.7},{area=392,location="Ratchet",node=80,t="fly"}},title="Vuela a {area:392}"},{goals={{map=1413,note="Adentro",npc=8496,npcName="Liv Rizzlefix",quest=4147,t="turnin",title="Marvon's Workshop",x=62.45,y=38.73},{count=1,item=10556,itemName="Stone Circle",map=1413,note="{item:10556}: {object:149036}",oi=1,quest=3444,t="collect",title="The Stone Circle",x=62.5,y=38.54}},note="El taller de Liv está en el extremo norte de los muelles de {area:392}; {object:149036} está adentro.",title="{npc:8496}"},{goals={{map=1413,npc=5901,npcName="Islen Waterseer",quest=5158,t="turnin",title="Seeking Spiritual Aid",x=65.83,y=43.78},{map=1413,npc=5901,npcName="Islen Waterseer",quest=5159,t="accept",title="Cleansed Water Returns to Felwood",x=65.83,y=43.78},{t="note",text="El agua purificada va a {area:2479}, en {zone:1448}: guárdala para después."}},note="{npc:5901} acampa en la orilla justo al norte de {area:392}.",title="{npc:5901}"},{goals={{item=248765,itemName="Sealed Apprentice Crate",t="collect"},{map=1413,npc=256386,npcName="Dokimi",quest=91899,t="turnin",title="A Sealed Crate",x=50.13,y=29.37},{item=248770,itemName="Sealed Apprentice Crate",t="collect"},{map=1413,npc=256386,npcName="Dokimi",quest=91904,t="turnin",title="A Sealed Crate",x=50.13,y=29.37}},note="Sube al norte por el camino hasta el Cruce; {npc:256386} está ahí. Abre cada caja que te dé y trae lo que haya adentro. Sigue en vuelo hasta {area:1237} desde el Cruce.",title="Las cajas de {npc:256386}"},{goals={{map=1413,t="goto",text="Maestro de vuelo del Cruce",x=51.5,y=30.4},{area=1237,location="Valormok",node=44,t="fly"}},title="Vuela a {area:1237}"},{goals={{map=1447,npc=8587,npcName="Jediga",quest=3517,t="accept",title="Stealing Knowledge",x=22.56,y=51.42},{map=1447,npc=8576,npcName="Ag'tor Bloodfist",quest=3505,t="accept",title="Betrayed",x=22.26,y=51.48},{map=1447,npc=247473,npcName="Izvi Gildfizz",quest=91568,t="accept",title="Long Walks on the Beach",x=22.53,y=51.84},{map=1447,note="{npc:247473}: {quest:91569}, una varita de los arcanistas elfos de sangre",npc=247473,npcName="Izvi Gildfizz",quest=91569,t="accept",title="Blue Gold",x=22.53,y=51.84}},title="{area:1237}"},{goals={{count=1,item=10540,itemName="Tablet of Markri",map=1447,oi=3,quest=3517,t="collect",title="Stealing Knowledge",x=34.2,y=57.8},{count=1,item=10538,itemName="Tablet of Beth'Amara",map=1447,oi=1,quest=3517,t="collect",title="Stealing Knowledge",x=35.19,y=58.02},{count=1,item=10541,itemName="Tablet of Sael'hai",map=1447,oi=4,quest=3517,t="collect",title="Stealing 